            return v[0], v[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def move_toward(src, dst, bias=(0, 0)):
        sx, sy = src
        tx, ty = dst
        return [clamp_step((tx - sx) + bias[0]), clamp_step((ty - sy) + bias[1])]

    def move_away(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    def valid_point(v):
        return isinstance(v, (list, tuple)) and len(v) >= 2

    def best_point(src, items, mode="near"):
        best = None
        best_score = None
