            elif mode == "far":
                if d > best_score:
                    best, best_score = p, d
            else:
                if d < best_score:
                    best, best_score = p, d
        return best

    def center_target(w, h):
        if w and h:
            return (w // 2, h // 2)
        return (0, 0)

    obs = observation if isinstance(observation, dict) else {}
    env = obs.get("environment_name") or obs.get("env") or obs.get("mode") or "resource_collection"

