    gw = obs.get("grid_width") or obs.get("width") or 0
    gh = obs.get("grid_height") or obs.get("height") or 0

    # Generic visible items
    resources = obs.get("resources") or obs.get("resource_positions") or obs.get("collectibles") or []
    targets = obs.get("unclaimed_cells") or obs.get("territory_targets") or obs.get("neutral_cells") or obs.get("frontier") or []
    own = obs.get("own_territory") or obs.get("territory") or []
    opp_terr = obs.get("opponent_territory") or obs.get("enemy_territory") or []

    if env == "pursuit_evasion":
        role = obs.get("self_role") or obs.get("role") or "pursuer"
        if role == "pursuer":
            # Chase opponent; if adjacent, keep pressure.
            if valid_point((ox, oy)):
