                    return move_toward((sx, sy), (ox, oy))
                return move_toward((sx, sy), (ox, oy))
            return [0, 0]
        # Evader: maximize distance from pursuer, prefer corners when ambiguous.
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        far_corner = best_point((ox, oy), corners, mode="far")
